    "subText": "<p style=\"margin-left:0px;\"><strong>Your generous support will enable our scholars to continue their education, enhance their skills and ensure a better future.</strong></p>",
    "expensesPerScholar": "<p style=\"margin-left:0cm;\">The expenses per scholar include:</p><ul style=\"list-style-type:disc;\"><li>University tuition fees</li><li>Transportation stipend</li><li>Training program fees</li></ul>",
